{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a lipophilic ester prodrug, has only 15% oral bioavailability in humans, demonstrating that ester prodrugs can fall below the 20% threshold; however, its polar guanidine/sugar scaffold limits transferability to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "DINCH, a highly lipophilic ester plasticizer, is almost completely bioavailable in humans, which would support high F, but it lacks the beta-lactone and N-formylleucine moieties of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "DEHP, another highly lipophilic ester, has ~25% oral bioavailability in human volunteers, just above the threshold; this is contradictory to a low prediction but the value is close to 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a long-chain ester prodrug, has 85±15% absolute oral bioavailability in children, contradicting low F; its simple ester prodrug design is not analogous to the query's beta-lactone lipase-inhibitor scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Perindopril, an ester prodrug, has 66% absolute oral bioavailability in humans, contradicting low F; it is much more polar and lacks the beta-lactone.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "DVAS, a long-chain ester/amide, has ~60% oral bioavailability in healthy volunteers, contradicting low F; its structure lacks the beta-lactone and formamide-leucine ester.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a beta-lactone lipase inhibitor designed for local gastrointestinal action; its systemic oral bioavailability is extremely low (<2% in humans), well below the 20% threshold. The high-F analogues are structurally distant and lack the beta-lactone/N-formylleucine pharmacophore, so they do not override the known low-absorption profile.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for orlistat/query is present in the provided evidence set.",
    "Most analogues are structurally distant and do not capture the beta-lactone/N-formylleucine pharmacophore responsible for the query's minimal absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

